/**
 * @method
 * @name scwin.tx_fn_ApplyJoin
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_ApplyJoin = async function () {
    const sbmOptions = {
        id: "tx_fn_ApplyJoin",
        method: "post",
        action: "/register/corpDiscls.do",
        ref: "dma_ApplyJoinReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil40206.tx_fn_ApplyJoin" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.applyJoin
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.applyJoin = async function () {
    /* sdd-asis-lifecycle:begin fn_ApplyJoin — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.corpDisclsChrgForm || { elements: [] });
    const loopCnt = 5;
    for (let i = 0; i < loopCnt; i++) {
        if (i == 2) {
            if (dma_hiddenStore.get("isInputContents3") === "N") {
                continue;
            }
        } else {
            if (i == 3) {
                if (dma_hiddenStore.get("isInputContents4") === "N") {
                    continue;
                }
            } else {
                if (i == 4) {
                    if (dma_hiddenStore.get("isInputContents5") === "N") {
                        continue;
                    }
                }
            }
        }
        if (!await scwin.chkForm(i)) {
            return;
        }
    }
    $c.util.getComponent('dma_ApplyJoinReq').set('method', 'registerCorpDisclsChrg');
    frm.action = 'corpDiscls.do';
    await scwin.tx_fn_ApplyJoin();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.chkForm
 * @author Inswave
 * @date 2026. 09. 29
 * @param formNo
 * @returns
 * @hidden N
*/
scwin.chkForm = async function (formNo) {
    /* sdd-asis-lifecycle:begin fn_ChkForm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.corpDisclsChrgForm || { elements: [] });
    if ($c.cm.fn_NullChk($c.util.getComponent(["ipt_chrgNm", "ipt_chrgNm_r1", "ipt_chrgNm_r2", "ipt_chrgNm_r3", "ipt_chrgNm_r4"][formNo]))) {
        return false;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = "성명"; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent(["ipt_chrgNm", "ipt_chrgNm_r1", "ipt_chrgNm_r2", "ipt_chrgNm_r3", "ipt_chrgNm_r4"][formNo]))) {
        return false;
    }
    if ($c.cm.fn_NullChk($c.util.getComponent(["ipt_jobtitlNm", "ipt_jobtitlNm_r1", "ipt_jobtitlNm_r2", "ipt_jobtitlNm_r3", "ipt_jobtitlNm_r4"][formNo]))) {
